320	  this.eventId = id
321	
322	  if (typeof global.addRuntimeLog === 'function') {
323	    global.addRuntimeLog('[detail] 打开 ID=' + id, 'info')
324	  }
325	
326	  if (id === undefined || id === null) {
327	    this.errorMsg = '事件ID无效'
328	    this.loading = false
329	    return
330	  }
331	
332	  this.checkFavoriteStatus(id)
333	
334	  // ==========================================================
