  },

  removeFavorite(idx) {
    var self = this
    var item = this.favorites[idx]
    if (!item) return
    var id = (typeof item === 'number') ? item : (item.id || 0)
    var newFavorites = []
    for (var i = 0; i < this.favorites.length; i++) {
      if (i !== idx) {
        newFavorites.push(this.favorites[i])
      }
    }
    self.favorites = newFavorites
